window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2b46624a43024bb2"]={"versions": [{"id": "FIG-2b46624a43024bb2", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition für die AUTOSAR Classic Platform (E2E-Bibliothek). Dargestellt ist die Struktur-Definition des Konfigurationstyps für das End-to-End-Kommunikationsschutzprofil 7 (E2E Profile 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Definierte Datenstruktur:</p>\n<ul class=\"fig-list\">\n<li><code>«structure» E2E::E2E_P07Types::E2E_P07ConfigType</code></li>\n</ul>\n<p class=\"fig-p\">Attribute (alle öffentlich, Sichtbarkeit <code>+</code>):</p>\n<ul class=\"fig-list\">\n<li><code>DataID :uint32</code>: Eindeutige Kennung der geschützten Datenverbindung.</li>\n<li><code>MaxDataLength :uint32</code>: Maximale zulässige Länge der Nutzdaten bzw. des Datenstroms in Bits.</li>\n<li><code>MaxDeltaCounter :uint32</code>: Maximal zulässige Differenz zwischen aufeinanderfolgenden Zählerständen.</li>\n<li><code>MinDataLength :uint32</code>: Minimale zulässige Länge der Nutzdaten bzw. des Datenstroms in Bits.</li>\n<li><code>Offset :uint32</code>: Bit-Offset für die Position des E2E-Headers innerhalb der geschützten Daten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Zustandsübergänge. Die Struktur definiert die statischen Parameter, die bei der Initialisierung und Laufzeitprüfung durch die E2E-Profile-7-Schutz- und Prüffunktionen (<code>E2E_P07Protect</code>, <code>E2E_P07Check</code>) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative C-Typdefinition (<code>struct</code>) für die Konfiguration von E2E Profile 7 innerhalb der E2E-Bibliothek. Alle Strukturmitglieder sind als vorzeichenlose 32-Bit-Ganzzahlen (<code>uint32</code>) modelliert. Implementierungen müssen sicherstellen, dass die Felder zur Compilezeit oder Initialisierungszeit gemäß den Kommunikationsanforderungen der geschützten Signalgruppe/PDU initialisiert und an die entsprechenden Bibliotheksfunktionen übergeben werden.</p>"}, {"id": "FIG-90b9af71955b7ebf", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition für die AUTOSAR Classic Platform (E2E-Bibliothek). Dargestellt ist die Struktur-Definition des Konfigurationstyps für das End-to-End-Kommunikationsschutzprofil 7 (E2E Profile 7).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Definierte Datenstruktur:</p>\n<ul class=\"fig-list\">\n<li><code>«structure» E2E_P07Types::E2E_P07ConfigType</code></li>\n</ul>\n<p class=\"fig-p\">Attribute (alle öffentlich, Sichtbarkeit <code>+</code>):</p>\n<ul class=\"fig-list\">\n<li><code>DataID: uint32</code>: Eindeutige Kennung der geschützten Datenverbindung.</li>\n<li><code>MaxDataLength: uint32</code>: Maximale zulässige Länge der Nutzdaten bzw. des Datenstroms in Bits.</li>\n<li><code>MaxDeltaCounter: uint32</code>: Maximal zulässige Differenz zwischen aufeinanderfolgenden Zählerständen.</li>\n<li><code>MinDataLength: uint32</code>: Minimale zulässige Länge der Nutzdaten bzw. des Datenstroms in Bits.</li>\n<li><code>Offset: uint32</code>: Bit-Offset für die Position des E2E-Headers innerhalb der geschützten Daten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Zustandsübergänge. Die Struktur definiert die statischen Parameter, die bei der Initialisierung und Laufzeitprüfung durch die E2E-Profile-7-Schutz- und Prüffunktionen (<code>E2E_P07Protect</code>, <code>E2E_P07Check</code>) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative C-Typdefinition (<code>struct</code>) für die Konfiguration von E2E Profile 7 innerhalb der E2E-Bibliothek. Alle Strukturmitglieder sind als vorzeichenlose 32-Bit-Ganzzahlen (<code>uint32</code>) modelliert. Implementierungen müssen sicherstellen, dass die Felder zur Compilezeit oder Initialisierungszeit gemäß den Kommunikationsanforderungen der geschützten Signalgruppe/PDU initialisiert und an die entsprechenden Bibliotheksfunktionen übergeben werden.</p>"}], "trans": [{"from": "FIG-2b46624a43024bb2", "to": "FIG-90b9af71955b7ebf", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Der Namespace-Pfad im Header der Datenstruktur wurde von <code>E2E::E2E_P07Types::E2E_P07ConfigType</code> auf <code>E2E_P07Types::E2E_P07ConfigType</code> verkürzt (Wegfall des übergeordneten Präfix <code>E2E::</code>).</li>\n<li>Die Formatierung der Attributdeklarationen wurde typografisch bereinigt (Entfall des Leerzeichens vor dem Doppelpunkt, z. B. <code>+ DataID: uint32</code> statt <code>+ DataID :uint32</code>).</li>\n</ul>"}]};
